<?php
 namespace Pterodactyl\Http\Controllers\Admin\Nodes; use Illuminate\View\View; use Illuminate\Http\Request; use Pterodactyl\Models\Node; use Illuminate\Support\Collection; use Pterodactyl\Models\Allocation; use Illuminate\Database\Eloquent\Builder; use Pterodactyl\Http\Controllers\Controller; use Pterodactyl\Repositories\Eloquent\NodeRepository; use Pterodactyl\Repositories\Eloquent\ServerRepository; use Pterodactyl\Traits\Controllers\JavascriptInjection; use Pterodactyl\Services\Helpers\SoftwareVersionService; use Pterodactyl\Repositories\Eloquent\LocationRepository; use Pterodactyl\Services\Dezerx\Allocations\PortCatalogue; use Pterodactyl\Services\Dezerx\Allocations\AllocationFolders; class NodeViewController extends Controller { use JavascriptInjection; public function __construct( private LocationRepository $locationRepository, private NodeRepository $repository, private ServerRepository $serverRepository, private SoftwareVersionService $versionService, ) { } public function index(Request $request, Node $node): View { $node = $this->repository->loadLocationAndServerCount($node); return view('admin.nodes.view.index', [ 'node' => $node, 'stats' => $this->repository->getUsageStats($node), 'version' => $this->versionService, ]); } public function settings(Request $request, Node $node): View { return view('admin.nodes.view.settings', [ 'node' => $node, 'locations' => $this->locationRepository->all(), ]); } public function configuration(Request $request, Node $node): View { return view('admin.nodes.view.configuration', compact('node')); } public function allocations(Request $request, Node $node): View { $sorted = AllocationFolders::enabled(); $folder = $sorted ? (string) $request->query('folder', AllocationFolders::ALL) : AllocationFolders::ALL; $filters = $this->filters($request); $query = Allocation::query() ->where('node_id', $node->id) ->orderByRaw('server_id IS NULL ASC') ->orderByRaw('COALESCE(server_id, 0) ASC') ->orderByRaw('INET_ATON(ip) ASC') ->orderBy('port') ->with(['server:id,name,allocation_id,egg_id', 'server.egg:id,name,uuid']); if ($sorted && $folder !== AllocationFolders::ALL) { AllocationFolders::narrow($query, $node->id, $folder); } $this->sift($query, $filters); $node->setRelation('allocations', $query->paginate(50)->withQueryString()); $this->plainInject(['node' => Collection::make([$node])->only(['id'])]); return view('admin.nodes.view.allocation', [ 'node' => $node, 'allocations' => Allocation::query()->where('node_id', $node->id) ->groupBy('ip') ->orderByRaw('INET_ATON(ip) ASC') ->get(['ip']), 'folders' => $sorted ? AllocationFolders::listing($node) : null, 'folder' => $folder, 'folderName' => $sorted ? AllocationFolders::label($node->id, $folder) : null, 'folderMeta' => $sorted ? AllocationFolders::meta($node->id, $folder) : [], 'catalogue' => $sorted ? PortCatalogue::categories() : [], 'groups' => $this->group($node), 'filters' => $filters, 'filtered' => $this->filtering($filters), 'matched' => $node->allocations->total(), 'freeOnNode' => Allocation::query()->where('node_id', $node->id)->whereNull('server_id')->count(), ]); } public function servers(Request $request, Node $node): View { $this->plainInject([ 'node' => Collection::make([$node->makeVisible(['daemon_token_id', 'daemon_token'])]) ->only(['scheme', 'fqdn', 'daemonListen', 'daemon_token_id', 'daemon_token']), ]); return view('admin.nodes.view.servers', [ 'node' => $node, 'servers' => $this->serverRepository->loadAllServersForNode($node->id, 25), ]); } private function filters(Request $request): array { return [ 'port_from' => $this->port($request->query('port_from')), 'port_to' => $this->port($request->query('port_to')), 'q' => mb_substr(trim((string) $request->query('q', '')), 0, 64), 'state' => in_array($request->query('state'), ['free', 'used'], true) ? (string) $request->query('state') : '', ]; } private function filtering(array $filters): bool { return $filters['port_from'] !== null || $filters['port_to'] !== null || $filters['q'] !== '' || $filters['state'] !== ''; } private function port(mixed $value): ?int { if (!is_numeric($value)) { return null; } $port = (int) $value; return $port >= 1 && $port <= 65535 ? $port : null; } private function sift(Builder $query, array $filters): void { if ($filters['port_from'] !== null) { $query->where('port', '>=', $filters['port_from']); } if ($filters['port_to'] !== null) { $query->where('port', '<=', $filters['port_to']); } if ($filters['state'] === 'free') { $query->whereNull('server_id'); } if ($filters['state'] === 'used') { $query->whereNotNull('server_id'); } if ($filters['q'] !== '') { $needle = '%' . str_replace(['%', '_'], ['\%', '\_'], $filters['q']) . '%'; $query->where(function (Builder $inner) use ($needle, $filters) { $inner->where('ip', 'LIKE', $needle) ->orWhere('ip_alias', 'LIKE', $needle) ->orWhereHas('server', fn (Builder $server) => $server->where('name', 'LIKE', $needle)); if (ctype_digit($filters['q'])) { $inner->orWhere('port', (int) $filters['q']); } }); } } private function group(Node $node): array { $ids = $node->allocations ->pluck('server_id') ->filter() ->unique() ->values() ->all(); $totals = $ids === [] ? [] : Allocation::query() ->where('node_id', $node->id) ->whereIn('server_id', $ids) ->selectRaw('server_id, COUNT(*) as total') ->groupBy('server_id') ->pluck('total', 'server_id') ->all(); $groups = []; $at = []; foreach ($node->allocations as $allocation) { if ($allocation->server_id === null) { $groups[] = ['server' => null, 'rows' => [$allocation], 'total' => 1]; continue; } if (!isset($at[$allocation->server_id])) { $at[$allocation->server_id] = count($groups); $groups[] = [ 'server' => $allocation->server, 'rows' => [], 'total' => (int) ($totals[$allocation->server_id] ?? 0), ]; } $groups[$at[$allocation->server_id]]['rows'][] = $allocation; } foreach ($groups as $index => $group) { $primary = $group['server']?->allocation_id; if ($primary === null || count($group['rows']) < 2) { continue; } usort( $groups[$index]['rows'], fn (Allocation $a, Allocation $b) => ($b->id === $primary ? 1 : 0) <=> ($a->id === $primary ? 1 : 0), ); } return $groups; } } 